def check(output, ctx):
    try:
        s = ctx['surface']
        for seg in segments(output):
            for c in seg:
                if not (c.isalpha() or c in s):
                    return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']
        if any(c.isspace() for c in s):
            return True
        return not any(any(c.isspace() for c in seg) for seg in segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']
        if s != s.lower():
            return True
        return all(seg == seg.lower() for seg in segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        return len(segments(output)) <= len(ctx['surface'])
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; seg = segments(output)
        if not seg or not s or not seg[0]:
            return True
        return seg[0][0].lower() == s[0].lower()
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; seg = segments(output)
        return sum(map(len, seg)) <= 2 * len(s) + 6
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; seg = segments(output)
        return sum(map(len, seg)) >= 0.5 * len(s) - 2
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']
        return all(len(x) <= len(s) + 5 for x in segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        import difflib
        s = ctx['surface']; j = ''.join(segments(output))
        if len(s) < 4:
            return True
        return difflib.SequenceMatcher(None, s.lower(), j.lower()).ratio() >= 0.4
    except Exception:
        return True

def check(output, ctx):
    try:
        seg = segments(output)
        if len(seg) != 1:
            return True
        return seg[0] == ctx['surface']
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']
        if any(c.isdigit() for c in s):
            return True
        return not any(c.isdigit() for c in ''.join(segments(output)))
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; j = ''.join(segments(output))
        for q in '"`\'':
            if q in j and q not in s:
                return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        s = set(ctx['surface'].lower())
        for x in segments(output):
            if len(x) >= 3 and not (set(x.lower()) & s):
                return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface'].lower(); seg = segments(output)
        f = seg[0].lower()
        k = min(2, len(f), len(s))
        if len(seg) == 1 or k == 0:
            return True
        return f[:k] == s[:k] or f[:1] == s[:1]
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; j = ''.join(segments(output))
        return not any(c in j and c not in s for c in '*_#[]()<>{}|')
    except Exception:
        return True

def check(output, ctx):
    try:
        j = ''.join(segments(output))
        return '->' not in j and '=' not in j
    except Exception:
        return True

def check(output, ctx):
    try:
        return len(segments(output)) <= len(ctx['surface']) // 2 + 2
    except Exception:
        return True

def check(output, ctx):
    try:
        seg = segments(output)
        if len(ctx['surface']) < 5 or len(seg) < 4:
            return True
        return not all(len(x) == 1 for x in seg)
    except Exception:
        return True

def check(output, ctx):
    try:
        seg = segments(output); s = ctx['surface']
        if len(seg) < 2:
            return True
        return s not in seg
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']
        if not s.isascii():
            return True
        return ''.join(segments(output)).isascii()
    except Exception:
        return True

def check(output, ctx):
    try:
        if '-' in ctx['surface']:
            return True
        return not any('-' in x for x in segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        if '/' in ctx['surface']:
            return True
        return not any('/' in x for x in segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        s = ctx['surface']; j = ''.join(segments(output))
        return not any(c in j and c not in s for c in ',;:')
    except Exception:
        return True

def check(output, ctx):
    try:
        if '.' in ctx['surface']:
            return True
        return '.' not in ''.join(segments(output))
    except Exception:
        return True

def check(output, ctx):
    try:
        from collections import Counter
        s = Counter(ctx['surface'].lower())
        j = Counter(''.join(segments(output)).lower())
        n = sum(s.values())
        if n < 5:
            return True
        cov = sum(min(s[c], j[c]) for c in s)
        return cov >= 0.5 * n
    except Exception:
        return True
